{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": ["Test"],
      "rationale": "The latency can be observed by feeding sensor updates and measuring display time, which is a behavior test."
    },
    {
      "requirement_id": "KK-002",
      "methods": ["Test"],
      "rationale": "Performance under load can be verified by running the software with 2,000 tracks and measuring refresh rate."
    },
    {
      "requirement_id": "KK-003",
      "methods": ["Test"],
      "rationale": "The displayed information can be checked by selecting a track and observing the shown ID, speed, direction, and timestamp."
    },
    {
      "requirement_id": "KK-004",
      "methods": ["Test"],
      "rationale": "The aging and removal behavior can be validated by monitoring a track with no updates for the specified periods."
    },
    {
      "requirement_id": "KK-005",
      "methods": ["Test"],
      "rationale": "Visual and audible alerts can be observed when a track enters a defined zone."
    },
    {
      "requirement_id": "KK-006",
      "methods": ["Test"],
      "rationale": "Message delivery time and status display can be measured by sending messages and timing receipt."
    },
    {
      "requirement_id": "KK-007",
      "methods": ["Test"],
      "rationale": "The immutable logging of operations can be verified by performing actions and inspecting the audit log for timestamps and user IDs."
    },
    {
      "requirement_id": "KK-008",
      "methods": ["Test"],
      "rationale": "Failover timing and data continuity can be tested by simulating primary server failure and measuring takeover time and data loss."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection of requests without a valid OAuth 2.0 token can be observed by sending such requests and verifying the HTTP 401 response."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Role‑based access enforcement is verified by invoking endpoints with clients of different roles and checking for HTTP 403 when access is not permitted."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "The rate‑limit of 600 requests per minute per client can be exercised and the resulting HTTP 429 and Retry‑After header observed."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Test"
      ],
      "rationale": "Latency impact is measured by generating 2,000 requests per second and recording the 99th‑percentile response time to ensure it stays ≤20 ms."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "A backend timeout can be simulated and the gateway’s termination behavior verified by checking for an HTTP 504 response."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Applying configuration changes during operation and confirming that the gateway continues processing in‑flight requests without restart validates this requirement."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "The presence and content of the configured log entries for each request can be inspected after exercising the gateway."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Monthly availability is a statistical measure that is calculated from operational data rather than observed in a single test run."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": ["Test"],
      "rationale": "The classification and confidence output can be observed by executing the service with sample documents."
    },
    {
      "requirement_id": "AI-002",
      "methods": ["Analiz"],
      "rationale": "Achieving a macro‑averaged F1 score requires statistical analysis of model predictions on a held‑out set."
    },
    {
      "requirement_id": "AI-003",
      "methods": ["Test"],
      "rationale": "Routing low‑confidence documents to a human queue can be verified by running the service with inputs that produce confidence below 0.60."
    },
    {
      "requirement_id": "AI-004",
      "methods": ["Test"],
      "rationale": "Response time for the 95th percentile can be measured by exercising the service under the specified load."
    },
    {
      "requirement_id": "AI-005",
      "methods": ["Test"],
      "rationale": "Recording of model version, input hash, and predicted category is observable in the service logs during execution."
    },
    {
      "requirement_id": "AI-006",
      "methods": ["Analiz"],
      "rationale": "Detecting a population stability index > 0.2 requires statistical analysis of weekly category distributions."
    },
    {
      "requirement_id": "AI-007",
      "methods": ["Test"],
      "rationale": "The three most influential text passages can be verified by inspecting the service output for a given classification."
    },
    {
      "requirement_id": "AI-008",
      "methods": ["Analiz"],
      "rationale": "Comparing recall across Turkish and English documents involves analytical evaluation of model performance per language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": ["Test"],
      "rationale": "The ability to log in with e-Devlet credentials can be observed by executing the system with valid and invalid credentials."
    },
    {
      "requirement_id": "KMU-002",
      "methods": ["Test"],
      "rationale": "Session timeout behavior can be verified by running the application, remaining idle for 15 minutes, and checking redirection to the login page."
    },
    {
      "requirement_id": "KMU-003",
      "methods": ["Test"],
      "rationale": "The lockout after five consecutive failed logins can be confirmed by attempting logins with wrong credentials and observing the 30‑minute lockout."
    },
    {
      "requirement_id": "KMU-004",
      "methods": ["Test"],
      "rationale": "File‑upload constraints (type and size) are verifiable by uploading files of various formats and sizes and observing acceptance or rejection."
    },
    {
      "requirement_id": "KMU-005",
      "methods": ["Test"],
      "rationale": "Generation of a unique tracking number and its email delivery can be validated by submitting applications and inspecting the received messages."
    },
    {
      "requirement_id": "KMU-006",
      "methods": ["Test"],
      "rationale": "Draft‑saving and restoration within 30 days can be checked by saving a partially completed form, waiting, and then resuming the session."
    },
    {
      "requirement_id": "KMU-007",
      "methods": ["İnceleme"],
      "rationale": "Compliance with WCAG 2.1 AA is assessed by reviewing design documents, UI code, and performing an accessibility audit."
    },
    {
      "requirement_id": "KMU-008",
      "methods": ["İnceleme"],
      "rationale": "Data residency requirements are verified by inspecting deployment configurations and infrastructure documentation to ensure servers are located within Turkey."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": ["Test"],
      "rationale": "The creation of a casualty record can be verified by executing the application and providing input, then observing the stored data."
    },
    {
      "requirement_id": "MED-002",
      "methods": ["Gösterim"],
      "rationale": "The distinct colour display for each triage category can be confirmed by running the UI and visually inspecting the colours."
    },
    {
      "requirement_id": "MED-003",
      "methods": ["Test"],
      "rationale": "Rejecting out‑of‑range vital‑sign values can be validated by supplying boundary and invalid inputs and observing the application's response."
    },
    {
      "requirement_id": "MED-004",
      "methods": ["Test"],
      "rationale": "Offline operation and the ability to store at least 500 records can be verified by disabling network access and creating 500 records, then checking persistence."
    },
    {
      "requirement_id": "MED-005",
      "methods": ["Test"],
      "rationale": "Synchronization and conflict‑resolution behavior can be observed by restoring connectivity after offline edits and inspecting the resulting records."
    },
    {
      "requirement_id": "MED-006",
      "methods": ["İnceleme"],
      "rationale": "Encryption with AES‑256 is confirmed by reviewing the code and configuration to ensure the correct algorithm and key size are used."
    },
    {
      "requirement_id": "MED-007",
      "methods": ["Test"],
      "rationale": "Operability with surgical gloves can be validated by having a user perform typical interactions while wearing gloves and observing successful operation."
    },
    {
      "requirement_id": "MED-008",
      "methods": ["Test"],
      "rationale": "Battery endurance of at least 8 hours can be measured by running the defined usage profile on a fully charged device and timing the discharge."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Device is powered on and a valid user session is active.",
      "test_inputs": "",
      "assumptions": "The application provides a function to export a stored casualty record for inspection.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record using the application UI.",
          "expected": "Record is saved on the device storage."
        },
        {
          "no": 2,
          "action": "Access the raw storage file where the record is stored (e.g., via file explorer or debug interface).",
          "expected": "The file content is not readable as plain text; it appears as binary data."
        },
        {
          "no": 3,
          "action": "Attempt to decrypt the file using an incorrect key.",
          "expected": "Decryption fails and produces unreadable output."
        },
        {
          "no": 4,
          "action": "Decrypt the file using the known AES-256 key used by the application.",
          "expected": "Decryption succeeds and the original casualty data is recovered correctly."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Battery endurance for 8‑hour usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Tablet is fully charged (100 % battery) and no background applications are running.",
      "test_inputs": "",
      "assumptions": "The defined usage profile consists of continuous patient triage entry, periodic image capture, and Wi‑Fi communication as specified in the system design.",
      "steps": [
        {
          "no": 1,
          "action": "Start the application and begin the defined usage profile.",
          "expected": "Application runs and battery level begins to decrease."
        },
        {
          "no": 2,
          "action": "Monitor battery level continuously until it reaches 0 % or the device powers off.",
          "expected": "Device remains operational for at least 8 hours before shutdown."
        },
        {
          "no": 3,
          "action": "Record the total elapsed time from start to shutdown.",
          "expected": "Elapsed time is ≥ 8 hours."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Battery endurance below required limit",
      "covers": [
        "MED-008"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "Tablet is fully charged and the usage profile is executed with an additional high‑intensity video streaming task.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Start the application and begin the defined usage profile plus the extra video streaming.",
          "expected": "Battery drains faster than in the nominal scenario."
        },
        {
          "no": 2,
          "action": "Observe when the device powers off.",
          "expected": "Device powers off before reaching 8 hours, indicating a failure of the requirement."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Configuration change applied without gateway restart",
      "covers": ["SW-006"],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Gateway is running and processing requests.",
      "test_inputs": "Change a configurable parameter (e.g., log level) via the management API.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Send a configuration change request to the gateway management API.",
          "expected": "The API returns a success response indicating the change was accepted."
        },
        {
          "no": 2,
          "action": "Verify that the gateway process ID remains the same.",
          "expected": "Process ID has not changed, indicating no restart occurred."
        },
        {
          "no": 3,
          "action": "Send a new client request through the gateway.",
          "expected": "The request is processed successfully using the new configuration value."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Configuration change does not drop in‑flight requests",
      "covers": ["SW-006"],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "Several long‑running requests (e.g., file download) are in flight.",
      "test_inputs": "Change a routing rule via the management API while requests are active.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Start multiple long‑running client requests through the gateway.",
          "expected": "All requests are accepted and are in progress."
        },
        {
          "no": 2,
          "action": "While the requests are in progress, submit a configuration change request.",
          "expected": "The configuration change is accepted without error."
        },
        {
          "no": 3,
          "action": "Observe the in‑flight requests until completion.",
          "expected": "All in‑flight requests complete successfully; none are aborted or return errors."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Logging of request metadata for each request",
      "covers": ["SW-007"],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Gateway logging is configured to write structured logs.",
      "test_inputs": "Send a HTTP GET request with known client ID and endpoint.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Send a HTTP GET request to /api/test with header X-Client-ID: client123.",
          "expected": "Gateway returns a 200 OK response."
        },
        {
          "no": 2,
          "action": "Read the latest log entry generated by the gateway.",
          "expected": "Log entry contains a tracking ID, client ID = client123, endpoint = /api/test, response code = 200, and a duration field."
        }
      ]
    },
    {
      "id": "TC-4",
      "title": "Error handling logging when request fails",
      "covers": ["SW-007"],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "Gateway is operational.",
      "test_inputs": "Send a request to a non‑existent endpoint.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Send a HTTP GET request to /nonexistent with header X-Client-ID: clientXYZ.",
          "expected": "Gateway returns a 404 Not Found response."
        },
        {
          "no": 2,
          "action": "Read the corresponding log entry.",
          "expected": "Log entry includes tracking ID, client ID = clientXYZ, endpoint = /nonexistent, response code = 404, and duration."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro‑averaged F1 score meets minimum requirement",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model has been trained and a held‑out evaluation set is available.",
      "test_inputs": "",
      "assumptions": "The evaluation script correctly computes macro‑averaged F1 according to the specification.",
      "steps": [
        {
          "no": 1,
          "action": "Run the model on the held‑out evaluation set and compute the macro‑averaged F1 score.",
          "expected": "The computed macro‑averaged F1 score is reported."
        },
        {
          "no": 2,
          "action": "Compare the reported score with the threshold 0.90.",
          "expected": "The score is greater than or equal to 0.90."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Macro‑averaged F1 score at the boundary value",
      "covers": [
        "AI-002"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The model has been tuned to produce a macro‑averaged F1 score close to 0.90.",
      "test_inputs": "",
      "assumptions": "The evaluation set is representative and the scoring algorithm is deterministic.",
      "steps": [
        {
          "no": 1,
          "action": "Execute the evaluation and obtain the macro‑averaged F1 score.",
          "expected": "The reported score is exactly 0.90."
        },
        {
          "no": 2,
          "action": "Verify that the requirement is considered satisfied.",
          "expected": "The system marks the requirement as met because the score meets the minimum."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Recall difference between Turkish and English documents within allowed limit",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The model has been evaluated separately on Turkish‑language and English‑language subsets of the held‑out set.",
      "test_inputs": "",
      "assumptions": "Recall is computed per language subset using the same definition.",
      "steps": [
        {
          "no": 1,
          "action": "Calculate recall for Turkish documents.",
          "expected": "Recall_Tur is reported."
        },
        {
          "no": 2,
          "action": "Calculate recall for English documents.",
          "expected": "Recall_Eng is reported."
        },
        {
          "no": 3,
          "action": "Compute the absolute difference |Recall_Tur – Recall_Eng|.",
          "expected": "The difference is less than or equal to 5 percentage points."
        }
      ]
    },
    {
      "id": "TC-4",
      "title": "Recall difference exceeds allowed limit (error case)",
      "covers": [
        "AI-008"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A model version that performs significantly better on one language than the other is deployed.",
      "test_inputs": "",
      "assumptions": "Recall values are obtained from the same evaluation run.",
      "steps": [
        {
          "no": 1,
          "action": "Measure recall for Turkish documents.",
          "expected": "Recall_Tur is reported."
        },
        {
          "no": 2,
          "action": "Measure recall for English documents.",
          "expected": "Recall_Eng is reported."
        },
        {
          "no": 3,
          "action": "Calculate the absolute difference |Recall_Tur – Recall_Eng|.",
          "expected": "The difference is greater than 5 percentage points, causing the requirement to be violated."
        }
      ]
    }
  ]
}

